L27_1 = "\229\133\146\229\173\144\239\188\140\233\155\150\231\132\182\231\136\184\231\136\184\229\170\189\229\170\189\229\190\136\230\131\179\228\189\160\239\188\140\228\189\134\228\189\160\229\183\178\231\182\147\230\152\175\229\164\167\228\186\186\228\186\134\239\188\140\229\191\133\233\160\136\233\155\162\233\150\139\231\136\182\230\175\141\231\154\132\230\135\183\230\138\177\228\186\134\227\128\130"
L26_1.m_Talk_TWN = L27_1
L27_1 = "\224\184\165\224\184\185\224\184\129\224\184\158\224\185\136\224\184\173 \224\184\158\224\185\136\224\184\173\224\184\163\224\184\185\224\185\137\224\184\167\224\185\136\224\184\178\224\184\165\224\184\185\224\184\129\224\184\132\224\184\180\224\184\148\224\184\150\224\184\182\224\184\135\224\185\128\224\184\163\224\184\178 \224\185\129\224\184\149\224\185\136\224\184\158\224\184\173\224\185\128\224\184\155\224\185\135\224\184\153\224\184\156\224\184\185\224\185\137\224\185\131\224\184\171\224\184\141\224\185\136\224\185\129\224\184\165\224\185\137\224\184\167\224\184\167\224\184\177\224\184\153\224\184\171\224\184\153\224\184\182\224\185\136\224\184\135\224\184\132\224\184\153\224\185\128\224\184\163\224\184\178\224\184\129\224\185\135\224\184\149\224\185\137\224\184\173\224\184\135\224\185\132\224\184\155\224\184\136\224\184\178\224\184\129\224\184\173\224\185\137\224\184\173\224\184\161\224\184\173\224\184\129\224\184\130\224\184\173\224\184\135\224\184\158\224\185\136\224\184\173\224\185\129\224\184\161\224\185\136\224\184\153\224\184\176"
L26_1.m_Talk_THA = L27_1
L27_1 = "Con trai c\225\187\167a m\225\186\185, m\225\186\185 bi\225\186\191t con \196\145\195\163 nh\225\187\155 ch\195\186ng ta, nh\198\176ng m\225\187\153t ng\195\160y n\195\160o \196\145\195\179 m\225\187\153t ng\198\176\225\187\157i \196\145\195\160n \195\180ng tr\198\176\225\187\159ng th\195\160nh ph\225\186\163i r\225\187\157i xa v\195\178ng tay c\225\187\167a cha m\225\186\185."
L26_1.m_Talk_VTN = L27_1
L27_1 = "\229\132\191\229\173\144\239\188\140\228\184\141\231\174\161\230\156\137\229\164\154\230\128\157\229\191\181\239\188\140\233\149\191\229\164\167\231\154\132\229\173\169\229\173\144\230\178\161\229\191\133\232\166\129\231\149\153\229\156\168\231\136\182\230\175\141\231\154\132\230\128\128\230\138\177\233\135\140\227\128\130"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Mein Sohn, ich wei\195\159, dass du uns vermisst hast, aber ein erwachsener Mann muss eines Tages die Umarmung seiner Eltern verlassen."
L26_1.m_Talk_DEU = L27_1
